I do it this way.

namespace KwiGCoder
{
    using System;
    using System.Collections.Generic;
    using System.Linq;
    using System.Text;
    using System.Threading.Tasks;

    public class MaterialCalculator
    {
        private readonly LengthUnits.Millimeter LAYERWIDTH = new(0.48);
        private readonly LengthUnits.Millimeter FILAMENT_DIAMETER = new(1.75);

        public LengthUnits.Millimeter RequierdRawFillament(Points3D.Point3D p1, Points3D.Point3D p2 , LengthUnits.Millimeter layerHeight)
        {

            LengthUnits.Millimeter radiusWidthEllipse = LAYERWIDTH / 2;
            LengthUnits.Millimeter radiusHeightEllipse = layerHeight / 2;
            AreaUnits.SquareMillimeter extrudeArea2DShape = Math.PI * radiusWidthEllipse * radiusHeightEllipse; // Ellipse

            LengthUnits.Millimeter distance = p2.AbsoluteDistanceTo(p1);
            VolumeUnits.QubeMillimeter rawFilamentVolumeNeeded = extrudeArea2DShape * distance;

            AreaUnits.SquareMillimeter areaOfUnextrudedFilament = (FILAMENT_DIAMETER.Half ^ 2) * Math.PI;

            var internalCorrectionFactor = 1.2;

            LengthUnits.Millimeter extrusionAmount = rawFilamentVolumeNeeded / areaOfUnextrudedFilament;
            extrusionAmount *= internalCorrectionFactor;


            if (extrusionAmount &lt;= new LengthUnits.Millimeter(0))
            {
                // Warn if a negative Value is returned.
                throw new Exception(&quot;Soaking up Filament is a planed feature ;-). But not implemented yet&quot;);
            }

            return extrusionAmount;

        }
    }
}
